1	// Package fileutil provides common file operations.
2	package fileutil
3	
4	import (
5		"bytes"
6		"crypto/sha256"
7		"errors"
8		"fmt"
9		"io"
10		"io/fs"
11		"os"
12		"path/filepath"
13	
14		"github.com/cameronsjo/bosun/internal/log"
15	)
16	
17	// ErrSymlinkSkipped is returned by CopyFile when the source is a symlink.
18	// Callers that walk directories should treat this as "not written" rather than
19	// a failure.
20	var ErrSymlinkSkipped = errors.New("symlink skipped")
21	
22	// warnSymlinkSkipped emits a structured warning when a symlink is encountered
23	// during a file copy operation and will be skipped.
24	func warnSymlinkSkipped(path string) {
25		linkTarget, readErr := os.Readlink(path)
26		l := log.Component(log.ComponentReconcile)
27		e := l.Warn().Str(log.FieldPath, path)
28		if readErr != nil {
29			e.Err(readErr).Msg("Skipping symlink during file copy")
30		} else {
31			e.Str("target", linkTarget).Msg("Skipping symlink during file copy")
32		}
33	}
34	
35	// CopyFile copies a single file from src to dst.
36	// It creates parent directories if needed and preserves permissions.
37	// Uses atomic write via temp file to prevent partial writes on failure.
38	// Symlinks are skipped with a warning rather than causing an error.
39	func CopyFile(src, dst string) error {
40		// Check if source is a symlink - Lstat doesn't follow symlinks
41		srcLstat, err := os.Lstat(src)
42		if err != nil {
43			return err // Return unwrapped to preserve os.IsNotExist compatibility
44		}
45		if srcLstat.Mode()&os.ModeSymlink != 0 {
46			warnSymlinkSkipped(src)
47			return ErrSymlinkSkipped
48		}
49	
50		srcFile, err := os.Open(src)
51		if err != nil {
52			return fmt.Errorf("open source: %w", err)
53		}
54		defer func() { _ = srcFile.Close() }()
55	
56		// Get source file info for permissions.
57		srcInfo, err := srcFile.Stat()
58		if err != nil {
59			return fmt.Errorf("stat source: %w", err)
60		}
61	
62		// Create parent directories if needed.
63		dstDir := filepath.Dir(dst)
64		if err := os.MkdirAll(dstDir, 0755); err != nil {
65			return fmt.Errorf("create parent directories: %w", err)
66		}
67	
68		// Create temp file in the same directory for atomic rename
69		tmpFile, err := os.CreateTemp(dstDir, ".tmp-*")
70		if err != nil {
71			return fmt.Errorf("create temp file: %w", err)
72		}
73		tmpPath := tmpFile.Name()
74	
75		// Ensure cleanup on any failure
76		success := false
77		defer func() {
78			if !success {
79				_ = tmpFile.Close()
80				_ = os.Remove(tmpPath)
81			}
82		}()
83	
84		// Copy content to temp file
85		if _, err := io.Copy(tmpFile, srcFile); err != nil {
86			return fmt.Errorf("copy content: %w", err)
87		}
88	
89		// Sync to ensure data is written to disk
90		if err := tmpFile.Sync(); err != nil {
91			return fmt.Errorf("sync temp file: %w", err)
92		}
93	
94		// Close temp file before rename
95		if err := tmpFile.Close(); err != nil {
96			return fmt.Errorf("close temp file: %w", err)
97		}
98	
99		// Set permissions to match source
100		if err := os.Chmod(tmpPath, srcInfo.Mode()); err != nil {
101			return fmt.Errorf("set permissions: %w", err)
102		}
103	
104		// Atomic rename to destination
105		if err := os.Rename(tmpPath, dst); err != nil {
106			return fmt.Errorf("rename to destination: %w", err)
107		}
108	
109		success = true
110		return nil
111	}
112	
113	// FileHash computes the SHA-256 hash of a file's contents.
114	// Returns the hash as a byte slice, or an error if the file cannot be read.
115	func FileHash(path string) ([sha256.Size]byte, error) {
116		f, err := os.Open(path)
117		if err != nil {
118			return [sha256.Size]byte{}, err
119		}
120		defer func() { _ = f.Close() }()
121	
122		h := sha256.New()
123		if _, err := io.Copy(h, f); err != nil {
124			return [sha256.Size]byte{}, fmt.Errorf("hash file: %w", err)
125		}
126	
127		var sum [sha256.Size]byte
128		copy(sum[:], h.Sum(nil))
129		return sum, nil
130	}
131	
132	// ContentEqual reports whether the file at path has content matching
133	// the given SHA-256 hash. Returns false if the file does not exist.
134	func ContentEqual(path string, srcHash [sha256.Size]byte) (bool, error) {
135		dstHash, err := FileHash(path)
136		if err != nil {
137			if os.IsNotExist(err) {
138				return false, nil
139			}
140			return false, err
141		}
142		return srcHash == dstHash, nil
143	}
144	
145	// CopyFileIfChanged copies src to dst only if the content differs.
146	// Returns true if the file was written, false if skipped (content identical).
147	// Uses SHA-256 content comparison to avoid unnecessary writes on FUSE filesystems.
148	// Includes a size-based confidence check to catch FUSE stale-read scenarios where
149	// the cached hash appears to match but the actual file content has diverged.
150	func CopyFileIfChanged(src, dst string) (bool, error) {
151		srcHash, err := FileHash(src)
152		if err != nil {
153			return false, fmt.Errorf("hash source: %w", err)
154		}
155	
156		equal, err := ContentEqual(dst, srcHash)
157		if err != nil {
158			return false, fmt.Errorf("compare destination: %w", err)
159		}
160		if equal {
161			// Confidence check: compare file sizes to catch FUSE stale-read scenarios.
162			// If the kernel-level file sizes differ, the hashes cannot truly match —
163			// the FUSE cache served stale content during hash comparison.
164			if sizesDiffer(src, dst) {
165				logger := log.Component(log.ComponentReconcile)
166				logger.Warn().
167					Str("src", src).
168					Str("dst", dst).
169					Msg("Content hash matched but file sizes differ (FUSE stale read?), forcing write")
170			} else {
171				// Read-back verification: compare raw bytes to catch hash computation
172				// bugs or FUSE cache inconsistencies that the size check didn't catch.
173				srcBytes, srcErr := os.ReadFile(src)
174				dstBytes, dstErr := os.ReadFile(dst)
175				if srcErr == nil && dstErr == nil && !bytes.Equal(srcBytes, dstBytes) {
176					logger := log.Component(log.ComponentReconcile)
177					logger.Warn().
178						Str("src", src).
179						Str("dst", dst).
180						Msg("Content hash matched but byte comparison differs (FUSE stale read?), forcing write")
181					// fall through to copy
182				} else {
183					return false, nil
184				}
185			}
186		}
187	
188		if err := CopyFile(src, dst); err != nil {
189			if errors.Is(err, ErrSymlinkSkipped) {
190				return false, nil
191			}
192			return false, err
193		}
194	
195		// Post-write verification: re-read destination hash to confirm the write landed.
196		// On FUSE mounts, the atomic rename may not immediately invalidate cached handles.
197		dstHash, verifyErr := FileHash(dst)
198		if verifyErr != nil {
199			logger := log.Component(log.ComponentReconcile)
200			logger.Warn().Err(verifyErr).Str(log.FieldPath, dst).Msg("Post-write verification: failed to re-read destination")
201		} else if dstHash != srcHash {
202			logger := log.Component(log.ComponentReconcile)
203			logger.Warn().Str(log.FieldPath, dst).Msg("Post-write verification: destination hash mismatch after write (FUSE cache stale)")
204		}
205	
206		return true, nil
207	}
208	
209	// sizesDiffer returns true if the two files have different sizes.
210	// Returns false if either file cannot be stat'd (caller falls through to hash).
211	func sizesDiffer(a, b string) bool {
212		aInfo, err := os.Stat(a)
213		if err != nil {
214			return false
215		}
216		bInfo, err := os.Stat(b)
217		if err != nil {
218			return false
219		}
220		return aInfo.Size() != bInfo.Size()
221	}
222	
223	// CopyDirIfChanged recursively copies a directory from src to dst,
224	// skipping files whose content has not changed. Returns relative paths
225	// of files that were actually written.
226	// Symlinks are skipped with a warning rather than causing an error.
227	func CopyDirIfChanged(src, dst string) ([]string, error) {
228		var written []string
229		err := filepath.WalkDir(src, func(path string, d fs.DirEntry, err error) error {
230			if err != nil {
231				return err
232			}
233	
234			if d.Type()&os.ModeSymlink != 0 {
235				warnSymlinkSkipped(path)
236				return nil
237			}
238	
239			relPath, err := filepath.Rel(src, path)
240			if err != nil {
241				return fmt.Errorf("calculate relative path: %w", err)
242			}
243			dstPath := filepath.Join(dst, relPath)
244	
245			if d.IsDir() {
246				return os.MkdirAll(dstPath, 0755)
247			}
248	
249			changed, err := CopyFileIfChanged(path, dstPath)
250			if err != nil {
251				return err
252			}
253			if changed {
254				written = append(written, relPath)
255			}
256			return nil
257		})
258		return written, err
259	}
260	
261	// CopyDir recursively copies a directory from src to dst.
262	// Symlinks are skipped with a warning rather than causing an error.
263	func CopyDir(src, dst string) error {
264		return filepath.WalkDir(src, func(path string, d fs.DirEntry, err error) error {
265			if err != nil {
266				return err
267			}
268	
269			// Symlinks are skipped: they may reference paths outside the staging dir
270			// and are not meaningful for the deploy target.
271			if d.Type()&os.ModeSymlink != 0 {
272				warnSymlinkSkipped(path)
273				return nil
274			}
275	
276			// Calculate destination path.
277			relPath, err := filepath.Rel(src, path)
278			if err != nil {
279				return fmt.Errorf("calculate relative path: %w", err)
280			}
281			dstPath := filepath.Join(dst, relPath)
282	
283			if d.IsDir() {
284				return os.MkdirAll(dstPath, 0755)
285			}
286	
287			return CopyFile(path, dstPath)
288		})
289	}
290

