				}, nil
			},
		}
		r := NewReconciler(cfg)
		r.reloadProjectConfig()
		assert.Equal(t, "root-hook", r.config.PostSyncHooks.Value[0].Container)
	})

	t.Run("no matching target is no-op", func(t *testing.T) {
		cfg := &Config{
			TargetName:    "pi",
			PostSyncHooks: NewConfigField([]PostSyncHook{{Container: "root-hook"}}),
