			},
		}
		r := NewReconciler(cfg)
		r.reloadProjectConfig()
		assert.Equal(t, "root-hook", r.config.PostSyncHooks.Value[0].Container)
	})

	t.Run("fast-path not short-circuited when only Targets present", func(t *testing.T) {
