func TestDecryptSecrets(t *testing.T) {
	t.Run("empty secrets files returns empty map", func(t *testing.T) {
		cfg := &Config{SecretsFiles: []string{}}
		r := NewReconciler(cfg)

		secrets, err := r.decryptSecrets(context.Background())
