		_, err := r.decryptSecrets(context.Background())
		require.Error(t, err)
		assert.Contains(t, err.Error(), "secrets file not found")
	})

	t.Run("successful decryption returns merged map", func(t *testing.T) {
		tmpDir := t.TempDir()
